add(slug="thermocouple", grp="Temperature", name="Thermocouple", kw="How a Thermocouple Works",
    title="How a Thermocouple Works: Animated Cold Junction Demo",
    desc="How a thermocouple works, animated: two metals make a small voltage from a temperature difference, and cold junction compensation gives the true temperature.",
    h1="How a Thermocouple Works",
    hero="Heat the hot junction and warm the terminals. See why the meter reads wrong without cold junction compensation and right with it. Uses real type K data.",
    quick="A thermocouple is two different metal wires joined at the measuring point. A temperature difference between that hot junction and the cold junction at the terminals creates a small voltage (Seebeck effect), and cold junction compensation adds back the terminal temperature.",
    sliders=[("th", "Hot junction temperature", 0, 1200, 400, 1, 0, "°C"), ("tc", "Terminal (cold junction) temperature", 0, 60, 30, 1, 0, "°C")],
    outs=[("eh", "EMF for hot junction vs 0 °C"), ("ec", "EMF for terminals vs 0 °C"), ("em", "Voltage the meter sees"), ("no", "Reading without CJC"), ("yes", "Reading with CJC")],
    legend=["Hot (measuring) junction", "Thermocouple wires, type K", "Cold junction at the terminals", "CJC sensor measuring terminal temperature", "Transmitter or meter"],
    steps=["Two different alloys are welded together at the tip; for type K they are Chromel and Alumel.",
           "Heating one end creates a voltage along each wire, and because the alloys differ, a net voltage appears.",
           "The voltage depends on the difference between the hot junction and the terminals.",
           "The meter measures the terminal temperature with a separate sensor (CJC).",
           "It adds the EMF for the terminal temperature, then converts the total to temperature using the standard table."],
    formula=["E(measured) = E(T hot) " + M + " E(T cold)", "E(T hot) = E(measured) + E(T cold)", "Example (type K): 400 °C = 16.397 mV, 30 °C = 1.203 mV",
             "Meter sees 15.194 mV; CJC adds 1.203 mV back"],
    parts=[("Hot junction", "Welded tip, grounded or ungrounded inside a sheath"), ("Thermocouple wires", "Pair of specific alloys, or matching extension cable"),
           ("Terminals", "Cold junction, where thermocouple metal meets copper"), ("CJC sensor", "RTD or thermistor measuring terminal temperature"),
           ("Transmitter", "Measures microvolts, applies CJC and linearisation")],
    pros=["Wide range, up to about 1260 °C for type K", "Rugged, small and fast responding", "Low cost and self powered"],
    cons=["Small signal, sensitive to noise", "Needs correct extension cable and CJC", "Less accurate and stable than an RTD"],
    faq=[("Why is it called the cold junction?", "It is the second junction, where the thermocouple wires connect to copper at the instrument. It is usually cooler than the measuring point."),
         ("What happens if CJC is missing?", "The reading is low by roughly the terminal temperature, as the demo shows. At 30 °C terminals, the error is close to 30 °C."),
         ("Why use extension cable?", "Ordinary copper wire would create a new junction at the wrong place. Extension cable keeps the same thermoelectric properties back to the terminals."),
         ("Is the mV to °C relation linear?", "Not exactly. Transmitters use the standard reference tables (IEC 60584) or polynomials to convert voltage to temperature.")],
    cal=[("temperature/thermocouple-calculator", "Thermocouple Calculator"), ("temperature/thermocouple-table", "Thermocouple Table")],
    glo=[("thermocouple", "Thermocouple"), ("seebeck-effect", "Seebeck Effect"), ("cold-junction-compensation", "Cold Junction Compensation")],
    cmp=[("rtd-vs-thermocouple", "RTD vs Thermocouple"), ("type-k-vs-type-j-thermocouple", "Type K vs Type J")],
    dl=("downloads/engineering-reference-tables/type-k-thermocouple-table", "Type K Thermocouple Table (Excel and PDF)"),
    blog=("cold-junction-compensation-in-thermocouple", "Cold junction compensation in thermocouple"))

